configFiles.template:
// ==================================================
// Call of Duty 2 Server Configuration
// Generated by TCAdmin - Do not edit manually if using the config editor
// ==================================================

// **************************************************
// *********** Server Security & Errors *************
// **************************************************

// Passwords
set rcon_password "${RconPassword}"
set sv_privatePassword "${PrivatePassword}"
set g_password "${PrivatePassword}"

// Logging
set g_log "server_mp.log"
set g_logSync "1"

// SV Pure / Cheats
set sv_pure "1"
set sv_cheats "0"

// Allowed Clans
set sv_allowedClan1 ""
set sv_allowedClan2 ""

// Disable Console
set sv_disableClientConsole "0"
set sv_reconnectlimit "3"

// **************************************************
// ************ Public Info *************************
// **************************************************

// SETS/PUBLIC INFO (stuff that shows up in server info)
sets g_needpass "0"
//sets IRC ""
//sets Admin ""
//sets Email ""
//sets URL ""

// **************************************************
// *********** Server Dvars *************************
// **************************************************

// Hostname and MOTD
sv_hostname "${Hostname}"
set scr_motd "Welcome to the server"

// Reserved Slots
set sv_privateClients "0"

// Downloads
seta sv_allowAnonymous "0"
set sv_allowdownload "1"

// Server Packet Rate
set sv_maxRate "25000"

// Limit Laggers and reconnect spammers
set sv_minPing "0"
set sv_maxPing "250"

// Banning
set g_banIPs ""

// AntiFlooding Settings
set sv_floodProtect "1"

// **************************************************
// ******************** Voice ***********************
// **************************************************

set sv_voice "0"
set sv_voiceQuality "1"

// **************************************************
// **************** Match Setup *********************
// **************************************************

// CTF
set scr_ctf_scorelimit "5"
