// ***************** Gameplay Dvars *****************
// **************************************************

// Team Icons
set scr_drawfriend "1"

// Friendly Fire
set scr_friendlyfire "0"

// Kill Cam & Spectate
set scr_killcam "0"
set scr_spectatefree "0"
