// Auto Team Balance
set scr_teambalance "1"

// Force Respawn
set scr_forcerespawn "1"

// **************************************************
// ******************* Voting ***********************
// **************************************************

set g_allowvote "0"

// **************************************************
// ************ Weapon Settings *********************
// **************************************************

// Weapon Ammo Pools
set g_weaponAmmoPools "0"

// Snipers
set scr_allow_enfieldsniper "1"
set scr_allow_kar98ksniper "1"
